responses.raw:
{
  "steps": [
    {
      "id": "select_one_area",
      "operation": "select_features",
      "arguments": {
        "input_path": "input_1",
        "output_path": "selected_landuse_area.parquet",
        "by": "field_equals",
        "field": "id",
        "value": "1"
      },
      "comment": "Selects the single land-use polygon (assumed identifier field 'id', value '1') that detail reduction applies to",
      "output": {"kind": "vector", "geometry": "polygon", "cardinality": "fewer"}
    },
    {
      "id": "simplify_selected_area",
      "operation": "simplify_layer",
      "arguments": {
        "input_path": "$select_one_area",
        "tolerance_meters": 50,
        "output_path": "simplified_landuse_area.parquet"
      },
      "output": {"kind": "vector", "geometry": "polygon", "cardinality": "same_as_input"}
    }
  ],
  "assumptions": [
    "selection_field=id",
    "selection_value=1 (the single land-use area to simplify, since input is a single landuse layer not multiple joined layers)",
    "tolerance_meters=50 (chosen level of corner-point reduction / detail loss)",
    "crs=metric_or_geographic_with_automatic_UTM_estimation (simplify_layer handles unit conversion)"
  ],
  "warnings": [
    "No explicit identifier field or value was provided to pick 'one of the joined land-use areas'; an assumed field ('id'='1') was used as a placeholder selection criterion.",
    "The simplification tolerance (50 meters) was chosen arbitrarily since the request did not specify how much detail to give up; adjust as needed."
  ]
}
